package com.hs.listing.model; import com.hs.listing.model.constant.ListingEnums.OperatingMode; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal;
@Entity @Table(name="listing_office_details") @Getter @Setter @NoArgsConstructor public class ListingOfficeDetail { @Id private String listingId; @MapsId @OneToOne(fetch=FetchType.LAZY) @JoinColumn(name="listing_id") private Listing listing; @Column(name="building_name") private String buildingName; @Column(name="office_grade") private String officeGrade; @Column(name="floor_number",nullable=false) private Integer floorNumber; @Column(name="handover_status",nullable=false) private String handoverStatus; @Column(name="expected_seats") private Integer expectedSeats; @Column(name="minimum_divisible_area_m2") private BigDecimal minimumDivisibleAreaM2; @Column(name="restroom_count") private Integer restroomCount; @Column(name="restroom_type") private String restroomType; @Column(name="pantry_type") private String pantryType; @Column(name="car_parking_capacity") private Integer carParkingCapacity; @Column(name="motorbike_parking_capacity") private Integer motorbikeParkingCapacity; @Enumerated(EnumType.STRING) @Column(name="operating_mode") private OperatingMode operatingMode; @OneToMany(mappedBy="listing",cascade=CascadeType.ALL,orphanRemoval=true) private java.util.List<ListingOfficeOperatingHour> operatingHours=new java.util.ArrayList<>(); }
